    for (int i = 0; i < 4; i++) {
        total += counter();
    }

    int extra = sumFirstN(3);

    printf("Total=%d Last=%d\n", total, counter());
    printf("Extra=%d\n", extra);

    return 0;
}

#include <stdio.h>

void modifyArray(int *arr, int size) {
    for (int i = 0; i < size; i++) {
        *(arr + i) = *(arr + i) * 2;
    }
}

int sumArray(int *arr, int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum;
}

int main() {
    int numbers[5] = {1, 2, 3, 4, 5};
    int *ptr = numbers;

    modifyArray(ptr, 5);

    printf("Array: ");
    for (int i = 0; i < 5; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    int total = sumArray(numbers, 5);
    printf("Sum: %d\n", total);

    return 0;
}

#include <stdio.h>

struct Student {
    char name[20];
    int marks;
};

int main() {
    struct Student students[3] = {
        {"Anu", 78},
        {"Ravi", 92},
        {"Kiran", 85}
    };

    int highestIndex = 0;
    for (int i = 1; i < 3; i++) {
        if (students[i].marks > students[highestIndex].marks) {
            highestIndex = i;
        }
    }

    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += students[i].marks;
    }

    printf("Topper: %s\n", students[highestIndex].name);
    printf("Average: %d\n", total / 3);

    return 0;
}

#include <iostream>
using namespace std;

class Shape {
public:
    virtual int area() {
        return 0;
    }
    virtual void describe() {
        cout << "Shape with area " << area() << endl;
    }
};

class Square : public Shape {
private:
    int side;
public:
    Square(int s) : side(s) {}
    int area() override {
        return side * side;
    }
};

class Rectangle : public Shape {
private:
    int width, height;
public:
    Rectangle(int w, int h) : width(w), height(h) {}
    int area() override {
        return width * height;
    }
};

int main() {
    Shape* shapes[2];
    shapes[0] = new Square(4);
    shapes[1] = new Rectangle(3, 5);

    for (int i = 0; i < 2; i++) {
        shapes[i]->describe();
    }

    return 0;
}

#include <iostream>
