int divide(int a, int b) {
    if (b == 0) {
        throw runtime_error("Division by zero");
    }
    return a / b;
}

int main() {
    int values[] = {10, 20, 0, 5};
    int total = 0;

    for (int i = 0; i < 4; i++) {
        try {
            int result = divide(100, values[i]);
            total += result;
            cout << "Result: " << result << endl;
        } catch (const exception& e) {
            cout << "Caught: " << e.what() << endl;
            total += 1;
        }
    }

    cout << "Total: " << total << endl;
    return 0;
}

