def counter_gen(n):
    total = 0
    for i in range(1, n + 1):
        total += i
        yield total


def process(n):
    gen = counter_gen(n)
    results = []
    for value in gen:
        if value % 2 == 0:
            results.append(value)
    return results


output = process(6)
print(output)

